import{j as e}from"./index-QoerxoIZ.js";const n=[],i=3,t={title:"Por que o design thinking é uma boa estratégia para o setor hoteleiro?",seoTitle:"Por que o design thinking é uma boa estratégia para o setor hoteleiro?",excerpt:"Entenda como usar tática para acelerar e melhorar negócios dentro do hotel Muito se fala da importância das estratégias de marketing para melhorar os negócios. No entanto, o contexto no qual as estratégias se configuram normalmente está voltado para a venda, em uma nova forma de fazer o consumidor enxergar valor em um determinado serviço ou produto, quando na verdade o grande segredo está na experiência: é através dela que o cliente se conecta com a empresa, e é justamente por meio dela que o marketing se torna “a alma do negócio”. Tendo a experiência como fator principal da jornada do cliente, é possível estabelecer uma série de estratégias, que auxiliam na fidelidade e taxa de satisfação do consumidor. Hoje, essa necessidade de ter um atendimento que contribua para a jornada é fundamental, até porque a centralidade do cliente é o que faz os negócios se moverem – e vale destacar que isso funciona de forma geral, para todos os setores. Assim, uma série de estratégias se tornam relevantes nessa trajetória. No setor hoteleiro, por exemplo, uma das táticas é o uso do design thinking. O que é o design thinking? Em linhas gerais, essa estratégia une a forma como",date:"2021-08-28",updatedAt:"2021-08-30",author:"foco-multimidia",category:"solucoes",tags:["design-thinking","hospedes","hoteis","hotelaria","pousadas"],coverImage:"/assets/imgs/blog/por-que-o-design-thinking-e-uma-boa-estrategia-para-o-setor-hoteleiro/WhatsApp-Image-2021-08-27-at-17.24.41-1.webp",ctaProduct:"sistema-de-gestao-hoteleira-pms"};function r(o){const a={a:"a",em:"em",h1:"h1",img:"img",p:"p",strong:"strong",...o.components};return e.jsxs(e.Fragment,{children:[e.jsx(a.p,{children:e.jsx(a.img,{src:"http://blogfocomultimid1.hospedagemdesites.ws/wp-content/uploads/2021/08/WhatsApp-Image-2021-08-27-at-17.24.41.jpeg",alt:""})}),`
`,e.jsx(a.p,{children:e.jsx(a.em,{children:"Entenda como usar tática para acelerar e melhorar negócios dentro do hotel"})}),`
`,e.jsx(a.p,{children:"Muito se fala da importância das estratégias de marketing para melhorar os negócios. No entanto, o contexto no qual as estratégias se configuram normalmente está voltado para a venda, em uma nova forma de fazer o consumidor enxergar valor em um determinado serviço ou produto, quando na verdade o grande segredo está na experiência: é através dela que o cliente se conecta com a empresa, e é justamente por meio dela que o marketing se torna “a alma do negócio”."}),`
`,e.jsx(a.p,{children:"Tendo a experiência como fator principal da jornada do cliente, é possível estabelecer uma série de estratégias, que auxiliam na fidelidade e taxa de satisfação do consumidor. Hoje, essa necessidade de ter um atendimento que contribua para a jornada é fundamental, até porque a centralidade do cliente é o que faz os negócios se moverem – e vale destacar que isso funciona de forma geral, para todos os setores. Assim, uma série de estratégias se tornam relevantes nessa trajetória."}),`
`,e.jsx(a.p,{children:"No setor hoteleiro, por exemplo, uma das táticas é o uso do design thinking."}),`
`,e.jsx(a.h1,{children:e.jsx(a.strong,{children:"O que é o design thinking?"})}),`
`,e.jsx(a.p,{children:"Em linhas gerais, essa estratégia une a forma como é enxergado o design com uma aplicação aos negócios, de forma não necessariamente visual. Ou seja, a ideia é promover uma experiência ao cliente que tenha dentro de si tudo o que um design pode passar ao consumidor, como apego emocional, cognitivo ou estético – uma nova forma de se relacionar com a marca, por meio do que é fornecido ao cliente durante sua jornada."}),`
`,e.jsx(a.p,{children:"A abordagem do design thinking, em resumo, nada mais é do que colocar o cliente no centro de forma inovadora, tornando-o parte de todo o processo. Ela propõe uma nova maneira de enxergar os negócios, baseada sobretudo em empatia, colaboração e experimentação. Na prática, é como olhar pelos olhos do consumidor: sentir suas dores e entender como ele deseja ser atendido."}),`
`,e.jsx(a.p,{children:"Em um contexto no qual o consumidor é o centro de tudo e sua experiência é uma das partes mais importantes de todo o negócio – como ocorre com hóspedes de hotéis –, essa estratégia se torna bastante importante."}),`
`,e.jsx(a.h1,{children:e.jsx(a.strong,{children:"Como usar essa estratégia para o setor hoteleiro?"})}),`
`,e.jsx(a.p,{children:"Usar o design thinking não apenas traz uma melhora significativa ao setor de hotéis – comprovada por resultados, vale salientar –, como também oferece uma inovação quase imediata à categoria. E isso pode ser visto, por exemplo, no caso Hyatt, uma grande rede de hotéis."}),`
`,e.jsx(a.p,{children:"Por meio de pesquisas com funcionários e clientes, a empresa percebeu que o consumidor tinha pouco controle sobre a própria experiência e pouco espaço para personalização. Os colaboradores também não tinham muita autonomia para tomar decisões e trazer soluções para o problema dos clientes. Foi a partir desse processo de estudo que a rede fez suas transformações: usar a empatia para sentir quais problemas poderiam ser solucionados, sentir as dores do consumidor, usar a colaboração dos funcionários e dar a eles treinamento e autonomia para trazer soluções mais adequadas e, por fim, experimentar novas formas de promover uma experiência única."}),`
`,e.jsx(a.p,{children:"O resultado de tudo isso foi visto de forma internacional: o Hyatt entrou pela primeira vez na lista de melhores empresas para se trabalhar nos Estados Unidos."}),`
`,e.jsx(a.p,{children:"É preciso lembrar sempre que a experiência é o fator principal para a sobrevivência de qualquer hotel. Ou seja, trazer uma jornada repleta de personalização, autonomia e empoderamento – por parte de funcionários e clientes – é fundamental para trazer um bom negócio."}),`
`,e.jsxs(a.p,{children:["O primeiro passo, vale destacar, é o estudo, a pesquisa profunda sobre todas as etapas da jornada do cliente. A partir disso, o design thinking ganha vida, por meio da capacitação de colaboradores, que são peças-chave em todo o processo – algo que pode ser aprendido em uma faculdade de ",e.jsx(a.a,{href:"https://www.cruzeirodosulvirtual.com.br/graduacao/administracao/",children:e.jsx(a.strong,{children:"administração EAD"})})," ou presencial –, e da empatia na hora de fechar um negócio com o consumidor."]}),`
`,e.jsx(a.p,{children:e.jsx(a.strong,{children:"Por Giovanna Scarparo"})}),`
`,e.jsx(a.p,{children:"Conversion"}),`
`,e.jsxs(a.p,{children:[e.jsx(a.em,{children:"Estagiária em Link Builder"})," – ",e.jsx(a.em,{children:"Agência Conversion"})]})]})}function d(o={}){const{wrapper:a}=o.components||{};return a?e.jsx(a,{...o,children:e.jsx(r,{...o})}):r(o)}export{d as default,t as frontmatter,i as readingTimeMin,n as toc};
